    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        if (n % 2 == 0) {
            System.out.println(n == 2 ? "PRIME" : "2");
            return;
        }
        for (long d = 3; d * d <= n; d += 2) {
            if (n % d == 0) {
                System.out.println(d);
                return;
            }
        }
        System.out.println("PRIME");
    }
}

