import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long x = sc.nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        long mod0 = ((a[0] % x) + x) % x;
        for (int i = 1; i < n; i++) {
            long m = ((a[i] % x) + x) % x;
            if (m != mod0) {
                System.out.println(-1);
                return;
            }
        }
        Arrays.sort(a);
        long median = a[n / 2];
        long ops = 0;
        for (long v : a) ops += Math.abs(v - median) / x;
        System.out.println(ops);
    }
}
